const fs = require('fs');
const LOG = '/home/x1/Music/.doctum_enviados.json';

const limpar = (v) =>
  v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim();

const digitos = (v) => {
  let d = String(v ?? '').replace(/\D/g, '');
  if (d.startsWith('55') && d.length > 11) d = d.slice(2);
  return d;
};

const chaveEnvio = (r) =>
  ((r['Nome'] + ' ' + r['Sobrenome']).replace(/\s+/g, ' ').trim() + '|' + digitos(r['Whatsapp'])).toLowerCase();

// Quem ja foi enviado pelo workflow B permanece como 'Enviado' mesmo recriando a planilha
let log = [];
try {
  log = JSON.parse(fs.readFileSync(LOG, 'utf8'));
} catch (e) {
  log = [];
}
const jaEnviados = new Set(Array.isArray(log) ? log : []);

const rows = $input.all()
  .map((item) => {
    const j = item.json;
    return {
      'Índice': 0,
      'Nome': limpar(j['Nome *'] ?? j['Nome']),
      'Sobrenome': limpar(j['Sobrenome *'] ?? j['Sobrenome']),
      'E-mail': limpar(j['E-mail'] ?? j['Email']),
      'Whatsapp': limpar(j['Whatsapp *'] ?? j['Whatsapp']),
      'Curso': limpar(j['Curso Pretendido'] ?? j['Curso']),
      'Unidade': limpar(j['Unidade Pretendida *'] ?? j['Unidade Pretendida']),
      'Modalidade': limpar(j['Modalidade']),
      'Escolaridade': limpar(j['Grau escolaridade'] ?? j['Escolaridade']),
      'Aceite Termos': limpar(j['Aceite Termos (SIM/NAO)'] ?? j['Aceite Termos']),
      'Status de Envio': limpar(j['Status de Envio']) || 'Pendente',
      'Captação': limpar(j['Captação do lead via'] ?? j['Captação']),
    };
  })
  .filter((r) => r['Nome'] !== '');

// Ordem alfabetica por Nome (pt-BR, ignorando acentos e maiusculas)
rows.sort((a, b) => {
  const c = a['Nome'].localeCompare(b['Nome'], 'pt-BR', { sensitivity: 'base' });
  if (c !== 0) return c;
  return a['Sobrenome'].localeCompare(b['Sobrenome'], 'pt-BR', { sensitivity: 'base' });
});

rows.forEach((r) => {
  if (jaEnviados.has(chaveEnvio(r))) r['Status de Envio'] = 'Enviado';
});

rows.forEach((r, i) => {
  r['Índice'] = i + 1;
});

return rows.map((r) => ({ json: r }));

const rows = $('Normalizar e ordenar').all().map((i) => i.json);
return [{
  json: {
    arquivo: '/home/x1/Music/candidatos_indexado.xlsx',
    total: rows.length,
    primeira: rows.length ? rows[0]['Nome'] : '',
    ultima: rows.length ? rows[rows.length - 1]['Nome'] : '',
  },
}];
